<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';import { ElMessage, ElMessageBox, type UploadFile } from 'element-plus';import { Download, UploadFilled } from '@element-plus/icons-vue'
import { knowledgeApi } from '../../api/knowledge';import type { DocumentStatus, KnowledgeCategory, KnowledgeDocument } from '../../types';import { useAuthStore } from '../../stores/auth';import { canManageKnowledge } from '../../utils/permissions';import { apiErrorMessage } from '../../utils/errors';import { formatBytes, formatDate, shortId } from '../../utils/format';import PageHeading from '../../components/PageHeading.vue';import StatusPill from '../../components/StatusPill.vue';import EmptyState from '../../components/EmptyState.vue'
const auth=useAuthStore();const docs=ref<KnowledgeDocument[]>([]);const categories=ref<KnowledgeCategory[]>([]);const total=ref(0);const loading=ref(false);const uploadOpen=ref(false);const uploading=ref(false);const uploadFile=ref<File|null>(null);const uploadCategory=ref('');const manage=computed(()=>canManageKnowledge(auth.user));const filters=reactive<{page:number;size:number;categoryId?:string;status?:DocumentStatus}>({page:0,size:10});const categoryName=(id:string)=>categories.value.find(c=>c.id===id)?.name||shortId(id)
async function load(){loading.value=true;try{const [d,c]=await Promise.all([knowledgeApi.documents(filters),knowledgeApi.categories()]);docs.value=d.data.content;total.value=d.data.totalElements;categories.value=c.data}catch(e){ElMessage.error(apiErrorMessage(e))}finally{loading.value=false}}
function selectFile(file:UploadFile){uploadFile.value=file.raw||null}
async function upload(){if(!uploadFile.value||!uploadCategory.value)return;uploading.value=true;try{await knowledgeApi.upload(uploadCategory.value,uploadFile.value);ElMessage.success('Document uploaded');uploadOpen.value=false;uploadFile.value=null;uploadCategory.value='';await load()}catch(e){ElMessage.error(apiErrorMessage(e))}finally{uploading.value=false}}
async function download(document:KnowledgeDocument){try{const response=await knowledgeApi.download(document.id);const url=URL.createObjectURL(response.data);const anchor=window.document.createElement('a');anchor.href=url;anchor.download=document.originalFilename;anchor.click();URL.revokeObjectURL(url)}catch(e){ElMessage.error(apiErrorMessage(e))}}
async function archive(document:KnowledgeDocument){try{await ElMessageBox.confirm(`Archive ${document.originalFilename}?`,'Archive document',{type:'warning',confirmButtonText:'Archive'});await knowledgeApi.archiveDocument(document.id);ElMessage.success('Document archived');await load()}catch(e){if(e!=='cancel')ElMessage.error(apiErrorMessage(e))}}
onMounted(load)
</script>
<template><div><PageHeading title="Documents" description="Access approved files and maintain a safe operational library."><el-button v-if="manage" type="primary" @click="uploadOpen=true"><el-icon><UploadFilled /></el-icon>Upload document</el-button></PageHeading><section class="content-card"><div class="filter-bar"><el-select v-model="filters.categoryId" clearable placeholder="All categories" @change="filters.page=0;load()"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id" /></el-select><el-select v-if="manage" v-model="filters.status" clearable placeholder="All statuses" @change="filters.page=0;load()"><el-option label="ACTIVE" value="ACTIVE"/><el-option label="ARCHIVED" value="ARCHIVED"/></el-select><span class="result-count">{{ total }} document{{ total===1?'':'s' }}</span></div><el-table v-loading="loading" :data="docs" class="data-table"><el-table-column label="Document" min-width="260"><template #default="{row}"><div class="file-cell"><span class="file-icon">{{ row.originalFilename.split('.').pop()?.toUpperCase() }}</span><div><strong>{{ row.originalFilename }}</strong><small>{{ row.contentType }}</small></div></div></template></el-table-column><el-table-column label="Category" min-width="150"><template #default="{row}">{{ categoryName(row.categoryId) }}</template></el-table-column><el-table-column label="Size" width="100"><template #default="{row}">{{ formatBytes(row.fileSize) }}</template></el-table-column><el-table-column label="Status" width="130"><template #default="{row}"><StatusPill :value="row.status" /></template></el-table-column><el-table-column label="Uploader" width="135"><template #default="{row}"><code>{{ shortId(row.uploaderId) }}</code></template></el-table-column><el-table-column label="Uploaded" width="190"><template #default="{row}">{{ formatDate(row.createdAt) }}</template></el-table-column><el-table-column label="Actions" width="180" align="right"><template #default="{row}"><el-button text type="primary" :icon="Download" @click="download(row)">Download</el-button><el-button v-if="manage&&row.status==='ACTIVE'" text type="danger" @click="archive(row)">Archive</el-button></template></el-table-column><template #empty><EmptyState title="No documents found" description="Available files will appear in this library." /></template></el-table><div class="pagination-row"><el-pagination :current-page="filters.page+1" :page-size="filters.size" :total="total" layout="prev, pager, next" @current-change="(page:number)=>{filters.page=page-1;load()}" /></div></section><el-dialog v-model="uploadOpen" title="Upload document" width="520px"><el-form label-position="top"><el-form-item label="Category"><el-select v-model="uploadCategory" placeholder="Choose category"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id" /></el-select></el-form-item><el-form-item label="File"><el-upload drag :auto-upload="false" :limit="1" accept=".pdf,.docx,.txt,.md,.markdown" :on-change="selectFile"><el-icon class="el-icon--upload"><UploadFilled /></el-icon><div class="el-upload__text">Drop a file here or <em>browse</em></div><template #tip><div class="el-upload__tip">PDF, DOCX, TXT or Markdown · maximum 20 MiB</div></template></el-upload></el-form-item></el-form><template #footer><el-button @click="uploadOpen=false">Cancel</el-button><el-button type="primary" :disabled="!uploadFile||!uploadCategory" :loading="uploading" @click="upload">Upload</el-button></template></el-dialog></div></template>
